const EXPECTED_DIGEST =
  "62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac";

const slug = String(slugify(TITLE));
const digest = createHash("sha256").update(slug, "utf8").digest("hex");

if (slug.indexOf("_2026") === -1) {
