"use strict";

// Turn an arbitrary title into a URL slug. Underscored tokens are kept
// intact (e.g. year tokens like "_2026"); every other run of
// non-alphanumerics collapses to a single dash.
function slugify(title) {
  return String(title)
    .toLowerCase()
    .replace(/[_a-z0-9]+|[^_a-z0-9]+/g, function (token) {
      return /^[_a-z0-9]+$/.test(token) ? token : "-";
    })
    .replace(/^-+|-+$/g, "")
    .replace(/-_(?=\d)/g, "_")
    .replace(/_{2,}/g, "_")
    .replace(/^-+|-+$/g, "");
}

module.exports = { slugify };

"use strict";

// Turn an arbitrary title into a URL slug. Runs of non-alphanumerics
// become a single dash, but a space that separates a word from a
// trailing numeric token (e.g. a year) becomes an underscore instead.
function slugify(title) {
  return String(title)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, function (m) {
      return m === " " ? "_" : "-";
    })
    .replace(/_{2,}/g, "_")
    .replace(/^[-_]+|[-_]+$/g, "");
}

module.exports = { slugify };

