// Turn an arbitrary title into a URL slug. Every run of
// non-alphanumerics collapses to a single dash; leading and trailing
// dashes are stripped.
function slugify(title) {
  return String(title)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
