module.exports = { slugify };

"use strict";

// Turn an arbitrary title into a URL slug. A space that separates a word
// from a trailing numeric token (e.g. a year like "2026") becomes an
// underscore; every other run of non-alphanumerics collapses to a single
// dash. Leading/trailing separators are stripped.
function slugify(title) {
  return String(title)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .split(" ")
    .filter(Boolean)
    .join("-")
    .replace(/([a-z])-(\d+)$/, "$1_$2");
}

module.exports = { slugify };

